from pathlib import Path
from docx import Document
from docx.enum.section import WD_ORIENT
from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT, WD_ROW_HEIGHT_RULE
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Inches, Pt

ROOT = Path(__file__).resolve().parents[1]

def cell_setup(cell, text, bold=False, size=7.7, font='Times New Roman'):
    cell.text=''
    p=cell.paragraphs[0]; p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_before=Pt(0); p.paragraph_format.space_after=Pt(0); p.paragraph_format.line_spacing=1.0
    r=p.add_run(str(text)); r.font.name=font; r._element.rPr.rFonts.set(qn('w:eastAsia'),font); r.font.size=Pt(size); r.bold=bold
    cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
    tcPr=cell._tc.get_or_add_tcPr(); mar=OxmlElement('w:tcMar')
    for side,val in [('top','65'),('start','65'),('bottom','65'),('end','65')]:
        e=OxmlElement('w:'+side); e.set(qn('w:w'),val); e.set(qn('w:type'),'dxa'); mar.append(e)
    tcPr.append(mar); borders=OxmlElement('w:tcBorders')
    for edge in ('top','left','bottom','right','insideH','insideV'):
        e=OxmlElement('w:'+edge); e.set(qn('w:val'),'single'); e.set(qn('w:sz'),'8'); e.set(qn('w:color'),'000000'); borders.append(e)
    tcPr.append(borders)

def add_table(doc,title,headers,rows,widths,size=7.5):
    p=doc.add_paragraph(); p.paragraph_format.space_before=Pt(8); p.paragraph_format.space_after=Pt(5)
    r=p.add_run(title); r.font.name='Times New Roman'; r._element.rPr.rFonts.set(qn('w:eastAsia'),'Times New Roman'); r.font.size=Pt(12.5); r.bold=True
    t=doc.add_table(rows=1,cols=len(headers)); t.autofit=False
    tr=t.rows[0]; tr.height=Inches(.58); tr.height_rule=WD_ROW_HEIGHT_RULE.AT_LEAST
    hp=tr._tr.get_or_add_trPr(); rep=OxmlElement('w:tblHeader'); rep.set(qn('w:val'),'true'); hp.append(rep)
    for i,h in enumerate(headers): cell_setup(tr.cells[i],h,True,size); tr.cells[i].width=Inches(widths[i])
    for row in rows:
        cells=t.add_row().cells; t.rows[-1].height=Inches(.43); t.rows[-1].height_rule=WD_ROW_HEIGHT_RULE.AT_LEAST
        for i,v in enumerate(row): cell_setup(cells[i],v,False,size); cells[i].width=Inches(widths[i])
    doc.add_paragraph()

def body(doc,text):
    p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(5); p.paragraph_format.line_spacing=1.05
    r=p.add_run(text); r.font.name='Times New Roman'; r._element.rPr.rFonts.set(qn('w:eastAsia'),'Times New Roman'); r.font.size=Pt(9)

def base_doc():
    d=Document(); s=d.sections[0]; s.orientation=WD_ORIENT.LANDSCAPE; s.page_width,s.page_height=s.page_height,s.page_width
    s.top_margin=s.bottom_margin=Inches(.55); s.left_margin=s.right_margin=Inches(.55); return d

